CREATE TABLE ai_feedback(id BIGINT NOT NULL,message_id BIGINT NOT NULL,user_id BIGINT NOT NULL,helpful BOOLEAN NOT NULL,comment VARCHAR(1000) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_ai_feedback_user_message(user_id,message_id),CONSTRAINT fk_ai_feedback_message FOREIGN KEY(message_id) REFERENCES ai_message(id) ON DELETE CASCADE);
